#!/usr/bin/env python3

'''Restores a Appy database from a bunch of file chunks as generated by the
   backup.'''

#- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
# ~license~

#- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
import os
from pathlib import Path

from appy.bin import Program
from appy.utils.path import Splitter
from appy.utils import string as sutils

#- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
HELP_FOL  = 'The folder containing the file chunks as generated by the ' \
            'standard Appy backup.'
HELP_FILE = 'The path to the file to reify. If not specified, the ' \
            'reconstituted file will be created in the current working ' \
            'directory, with a name based on the names of the chunks.'
DIR_KO    = 'Folder %s does not exist or is not a folder.'
DIR_E     = 'Folder %s is empty.'
FILE_E    = 'File to generate, %s, already exists.'
DIR_WG    = 'All files in %s must share the same prefix, which is not the case.'
REST_RUN  = 'Restoring Appy database %s from %d chunk·s as found in %s...'
REST_DONE = 'Done.'

#- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
class Restore(Program):
    '''Restores a Appy database from a folder containing chunks of a Appy
       database as generated by the standard Appy backup.'''

    def defineArguments(self):
        '''Define the allowed arguments for this program'''
        parser = self.parser
        add = parser.add_argument
        # Positional arguments
        add('folder', help=HELP_FOL)
        # Optional arguments
        add('-f', '--file', dest='file', help=HELP_FILE)

    def getCommonPrefix(self, folder):
        '''Returns, as a 2-tuple, the prefix being common to all files in this
           p_folder, and the count of these files.'''
        r = None
        count = 0
        for path in folder.glob('*.*'):
            count += 1
            if r is None:
                r = path.name
            else:
                r = sutils.getCommonPrefix(r, path.name)
        return r, count

    def analyseArguments(self):
        '''Check and store arguments'''
        args = self.args
        # Get the folder where chunks lie
        self.folder = folder = Path(args.folder)
        if not folder.is_dir():
            self.exit(DIR_KO % folder)
        if not any(folder.iterdir()):
            self.exit(DIR_E % folder)
        # Ensure p_self.folder is an aboslute path
        folder = self.folder = folder.resolve()
        # Identify the common prefix between the names of all files lying in
        # v_folder.
        prefix, self.count = self.getCommonPrefix(folder)
        if not prefix:
            self.exit(DIR_WG % folder)
        # Determine the path to the file to reify
        path = args.file
        if not path:
            # Create the file name based on p_prefix, removing dots and chunk
            # numbers.
            base = prefix.split('.', 1)[0]
            path = Path(os.getcwd()) / f'{base}.fs'
        else:
            path = Path(path)
        # Never overwrite an existing database
        if path.is_file():
            self.exit(FILE_E % path)
        self.path = path

    def do(self):
        '''Restore, in p_self.path, the dabatase file from its chunks as stored
           in p_self.folder.'''
        print(REST_RUN % (self.path, self.count, self.folder))
        # Reify a splitted file is a task the Splitter can do. The Splitter is
        # the class that has initially splitted the file into chunks.
        splitter = Splitter(self.path, destFolder=self.folder, overwrite=False)
        splitter.reify()
        print(REST_DONE)

#- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
if __name__ == '__main__':
    Restore().do()
#- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
